// scope: "managed" | "user" (~/.claude/CLAUDE.md, ~/.claude/rules) | "parent" (a folder above the working folder) | "project" (the working folder)
//        | "nested" (a subfolder: loads when Claude works there) | "memory" (the auto-memory folder) | "generated" (mike-lessons.md, written by mike).
// loads: "launch" = in context from the start of the session; "on-demand" = loads when a matching or nested file is opened (path-scoped rules, subfolders, memory topic files); "no" = present but not read.
interface RuleFile { repo?: string; order: number; path: string; scope: string; loads: "launch" | "on-demand" | "no"; lines: number; bytes: number; tokens: number; items: number | null;
  generated?: true; paths?: string[]; note?: string; importedBy?: string; sameContentAs?: string; truncated?: true; skipped?: true }
// An item is one bullet, numbered item, table row or paragraph (code blocks, headings and comments are not items). at is "path:line".
interface RuleItem { at: string; scope: string; repo?: string; generated?: true; lesson?: number; heading?: string; text: string }
interface Change { action: string; file: string; line?: number; removed?: string; added?: string; backup: string | null; warning?: string }

declare const rules: {
  cwd: string;  // the folder the calling agent works in: what every call resolves for when no folder is given
  act: boolean; // true when this ask may change things

  // Every instruction file that loads or may load for a folder, in load order: managed, user (~/.claude/CLAUDE.md, ~/.claude/rules), then each folder from the
  // filesystem root down to the folder (CLAUDE.md, .claude/CLAUDE.md, .claude/rules/**, AGENTS.md when no CLAUDE.md exists at or above, CLAUDE.local.md; @imports follow
  // their importer), the memory folder, then files in subfolders. tokens are bytes/4. totals: per scope. launch.tokens: what is in context at the start.
  // o.topics false (default here) sums memory topic files in one entry; o.nested false skips subfolders; o.nestedMax (default 30) caps nested files shown.
  loaded(folder?: string, o?: { topics?: boolean; launchOnly?: boolean; nested?: boolean; nestedMax?: number }): Promise<{
    folder: string; gitRoot: string | null; instructionFiles: string; agentsMdRead: boolean; files: RuleFile[];
    totals: Record<string, { files: number; items: number; lines: number; bytes: number; tokens: number }>; launch: { files: number; tokens: number };
    memory: { dir: string | null; expected: string; exists: boolean; existsAbove?: string[] }; notes: string[]; warnings: string[] }>;

  // Rule items about a subject across every layer, best match first. subject: plain words (any word matches, rarer words and more matches rank higher; stems match).
  // o.pattern: a regex on the item text instead. o.all: every word must match. o.scope: one scope. o.lessons: only lines of mike's lessons file (each has its lesson id).
  // filesHolding says which files hold the matches. Items in a second copy of an identical file are skipped.
  find(subject: string, o?: { folder?: string; pattern?: string; all?: boolean; scope?: string; lessons?: boolean; max?: number; width?: number }): Promise<{
    folder: string; subject: string; terms: string[]; searched: { files: number; items: number }; matches: number; shown: number;
    results: (RuleItem & { score: number; matched: string })[]; filesHolding: { path: string; matches: number }[] }>;

  // Items per file and per scope. total.written is items not generated by mike; total.atLaunch is items in files that load at launch.
  count(folder?: string, o?: { max?: number }): Promise<{ folder: string; total: { files: number; items: number; atLaunch: number; generatedByMike: number; written: number };
    perScope: Record<string, { files: number; items: number }>; perFile: { path: string; scope: string; loads: string; items: number; kinds: Record<string, number>; generated?: true }[];
    sizes: Record<string, { files: number; items: number; lines: number; bytes: number; tokens: number }>; launch: { files: number; tokens: number } }>;

  // Pairs of items in different files that overlap (Jaccard of content words >= threshold, default 0.5; or one contains the other). sameFileName: both files have
  // the same name (a copy or backup). A pair with a lesson from mike is changed in mike.
  duplicates(folder?: string, o?: { threshold?: number; within?: boolean; max?: number; minWords?: number }): Promise<{
    itemsCompared: number; pairs: number; shown: number; duplicates: { similarity: number; kind: string; sameFileName?: true; a: RuleItem; b: RuleItem; note?: string }[] }>;

  // Candidate contradictions from wording: one item always/must, the other never/don't, on the same subject; or different numbers for the same words. Candidates only.
  conflicts(folder?: string, o?: { minOverlap?: number; max?: number }): Promise<{
    itemsCompared: number; candidates: number; shown: number;
    conflicts: { kind: "opposite wording" | "different numbers"; overlap: number; shared: string[]; values?: { a: string[]; b: string[] }; a: RuleItem & { says?: string }; b: RuleItem & { says?: string } }[] }>;

  // Items that name something missing: kind "missing path" (a backticked path; abbreviated paths such as ui/motion.css are looked up in the repository), "missing command"
  // (after run/call/invoke, not on PATH: an alias would not show), "missing skill" / "missing agent", "broken link", "broken memory link", "date in the past",
  // "temporary wording". confidence high | medium | low. memoryIssues: the memory folder's index and front matter problems.
  stale(folder?: string, o?: { max?: number }): Promise<{ checked: Record<string, number>; findings: number; byKind: Record<string, number>; shown: number;
    stale: { kind: string; at: string; scope: string; ref: string; why: string; confidence: string; text: string; generated?: true }[]; memoryIssues: { at: string; issue: string; confidence?: string }[] }>;

  // A numbered text of an instruction file (CLAUDE.md, AGENTS.md, CLAUDE.local.md, .claude/rules/*.md, or a memory file). Up to 400 lines. Refuses anything else: credentials,
  // ~/.claude.json, transcripts. Reading a file is what lets a change to it be made.
  read(file: string, o?: { from?: number; to?: number }): { file: string; from: number; to: number; lines: number; bytes: number; generated?: true; frontmatter?: Record<string, any>; text: string };
  // The rule items of one file.
  items(file: string): (RuleItem & { kind: string; endLine: number })[];
  // Every memory folder under ~/.claude/projects: {slug, dir, files, bytes, index}. The slug is the project path with each non-alphanumeric character replaced by "-".
  memoryDirs(): { slug: string; dir: string; files: number; bytes: number; index: string }[];
  slug(absolutePath: string): string;

  // Changes. Each throws "not in this ask: ..." unless rules.act is true. Each needs the file read first in this ask (rules.read) and refuses when the file changed since
  // (another session edited it). A file generated by mike (mike-lessons.md) is never changed: lessons are changed in mike. A copy of the old file goes to the backup folder
  // and is named in the result. Every result says what was removed and added.
  edit(file: string, from: string, to: string, o?: { all?: boolean }): Change;   // exact text: one occurrence, or all with { all: true }; to "" deletes
  write(file: string, text: string): Change;                                      // a whole file (a new rule file, or a rewrite); a memory file needs front matter
  remove(file: string): Change;                                                    // delete a file (kept in the backup folder)
  // Write one memory (front matter name, description, metadata.type) and its line in MEMORY.md. type: user | feedback | project | reference; feedback and project bodies carry
  // "**Why:**" and "**How to apply:**". file: a bare name (feedback_x.md). Refuses an existing file, and an index that would pass 200 lines or 25 KB.
  remember(o: { file: string; name: string; description: string; type: "user" | "feedback" | "project" | "reference"; body: string; hook?: string; folder?: string; dir?: string }): Promise<Change & { indexLine: string; similarExisting: { at: string; text: string }[] }>;
  // Delete one memory topic file and its line in MEMORY.md (read the file first).
  forget(file: string): Promise<Change & { indexLineRemoved: string | null }>;
  // Everything changed so far in this ask.
  changes(): Change[];
};
